def A(name,ln,units,p,title,text):
 a={'id':'rst31-cooking1-'+name,'lessonId':L(ln),'titleJa':title,'textJa':text,'unitIds':[U(n) for n in units],'factIds':[],'sourceRefs':refs(p,title)};adds.append(a);return a['id']
